private static int findClosest(Tile[] tiles,float x,float y){
  int cindex=-2;
  float dst=Float.MAX_VALUE;
  for (int i=0; i < tiles.length - 1; i++) {
    Tile tile=tiles[i];
    Tile next=tiles[i + 1];
    float d=pointLineDist(tile.worldx(),tile.worldy(),next.worldx(),next.worldy(),x,y);
    if (d < dst) {
      dst=d;
      cindex=i;
    }
  }
  return cindex + 1;
}
